parameters.jsCode:
const groqItem = $input.first().json;
const webhookData = $('Job Complete Webhook').first().json.body || {};

let emailBody = groqItem.choices?.[0]?.message?.content || '';
emailBody = emailBody.trim();

if (!emailBody) {
  emailBody = `Hi ${webhookData.customerName || 'there'},\n\nThank you for choosing ${webhookData.businessName || 'us'} for your recent ${webhookData.jobType || 'service'}. We hope everything went smoothly.\n\nIf you have a moment, we would really appreciate it if you could leave us a Google review — it makes a huge difference to a small business.\n\n[GOOGLE_REVIEW_LINK]\n\nThank you so much.`;
}

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      customerName: webhookData.customerName || '',
      customerEmail: webhookData.customerEmail || '',
      jobType: webhookData.jobType || '',
      businessName: webhookData.businessName || '',
      emailBody: emailBody,
      emailSubject: `Thank you for choosing ${webhookData.businessName || 'us'} — quick favour`
    }
  }
];
